#!/usr/bin/env bash
# Wave one, drafted by gate/tools/wave.py (F14-T11): one intake import-fc per target,
# each with its catalog evidence (F14-R4). Read every draft first (R13).
# One target per pull request (F11-Q26): run with --branch per target, or import on
# main and split.
#
#   <out>/import.sh [../open_proof_network_graph] [--sandbox]
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(git -C "$HERE" rev-parse --show-toplevel)"
GRAPH="${1:-$ROOT/../open_proof_network_graph}"
MODE="${2:---no-toolchain}"
NETWORK="${NETWORK:-$(git -C "$ROOT" rev-parse HEAD)}"
AUTHOR="${AUTHOR:-thisisanameforsure}"
PIN=d8d031d4998c78575159ccab9a7a9e95ce043883
export PYTHONPATH="$ROOT/gate${PYTHONPATH:+:$PYTHONPATH}"
uv run --frozen --project "$ROOT" python -m opn_gate.cli intake import-fc "$HERE/upstream/FormalConjectures/GreensOpenProblems/58.lean" --at "$PIN" --graph "$GRAPH" --target green-58 --from "$HERE/green-58/record.yaml" --witness "$HERE/green-58/Witness.lean" --statement "$HERE/green-58/Statement.lean" --defs "$HERE/green-58/defs" --hazards "$HERE/green-58/hazards.yaml" --path FormalConjectures/GreensOpenProblems/58.lean --repo google-deepmind/formal-conjectures --url "https://github.com/google-deepmind/formal-conjectures/blob/$PIN/FormalConjectures/GreensOpenProblems/58.lean" --licence Apache-2.0 --attribution "The Formal Conjectures Authors (google-deepmind/formal-conjectures), Apache-2.0" --upstream-author "The Formal Conjectures Authors" --author "$AUTHOR" --evidence-from "$ROOT/docs/lean_conjecture_catalog.json" --key fc:FormalConjectures/GreensOpenProblems/58.lean#green_58 --network-commit "$NETWORK" $( [ "$MODE" = "--sandbox" ] && echo --sandbox || echo --no-toolchain ) | tail -3
uv run --frozen --project "$ROOT" python -m opn_gate.cli intake import-fc "$HERE/upstream/FormalConjectures/Paper/ReedOmegaDeltaChi.lean" --at "$PIN" --graph "$GRAPH" --target reed-omega-delta-chi-conjecture --from "$HERE/reed-omega-delta-chi-conjecture/record.yaml" --witness "$HERE/reed-omega-delta-chi-conjecture/Witness.lean" --statement "$HERE/reed-omega-delta-chi-conjecture/Statement.lean" --defs "$HERE/reed-omega-delta-chi-conjecture/defs" --path FormalConjectures/Paper/ReedOmegaDeltaChi.lean --repo google-deepmind/formal-conjectures --url "https://github.com/google-deepmind/formal-conjectures/blob/$PIN/FormalConjectures/Paper/ReedOmegaDeltaChi.lean" --licence Apache-2.0 --attribution "The Formal Conjectures Authors (google-deepmind/formal-conjectures), Apache-2.0" --upstream-author "The Formal Conjectures Authors" --author "$AUTHOR" --evidence-from "$ROOT/docs/lean_conjecture_catalog.json" --key fc:FormalConjectures/Paper/ReedOmegaDeltaChi.lean#reed_omega_delta_chi_conjecture --network-commit "$NETWORK" $( [ "$MODE" = "--sandbox" ] && echo --sandbox || echo --no-toolchain ) | tail -3
uv run --frozen --project "$ROOT" python -m opn_gate.cli intake import-fc "$HERE/upstream/FormalConjectures/Wikipedia/FlintCooksonHills.lean" --at "$PIN" --graph "$GRAPH" --target flint-hills-series-converges --from "$HERE/flint-hills-series-converges/record.yaml" --witness "$HERE/flint-hills-series-converges/Witness.lean" --statement "$HERE/flint-hills-series-converges/Statement.lean" --hazards "$HERE/flint-hills-series-converges/hazards.yaml" --path FormalConjectures/Wikipedia/FlintCooksonHills.lean --repo google-deepmind/formal-conjectures --url "https://github.com/google-deepmind/formal-conjectures/blob/$PIN/FormalConjectures/Wikipedia/FlintCooksonHills.lean" --licence Apache-2.0 --attribution "The Formal Conjectures Authors (google-deepmind/formal-conjectures), Apache-2.0" --upstream-author "The Formal Conjectures Authors" --author "$AUTHOR" --evidence-from "$ROOT/docs/lean_conjecture_catalog.json" --key fc:FormalConjectures/Wikipedia/FlintCooksonHills.lean#flint_hills_series_converges --network-commit "$NETWORK" $( [ "$MODE" = "--sandbox" ] && echo --sandbox || echo --no-toolchain ) | tail -3
uv run --frozen --project "$ROOT" python -m opn_gate.cli intake import-fc "$HERE/upstream/FormalConjectures/Wikipedia/GoldbachConjecture.lean" --at "$PIN" --graph "$GRAPH" --target goldbach --from "$HERE/goldbach/record.yaml" --witness "$HERE/goldbach/Witness.lean" --statement "$HERE/goldbach/Statement.lean" --hazards "$HERE/goldbach/hazards.yaml" --path FormalConjectures/Wikipedia/GoldbachConjecture.lean --repo google-deepmind/formal-conjectures --url "https://github.com/google-deepmind/formal-conjectures/blob/$PIN/FormalConjectures/Wikipedia/GoldbachConjecture.lean" --licence Apache-2.0 --attribution "The Formal Conjectures Authors (google-deepmind/formal-conjectures), Apache-2.0" --upstream-author "The Formal Conjectures Authors" --author "$AUTHOR" --evidence-from "$ROOT/docs/lean_conjecture_catalog.json" --key fc:FormalConjectures/Wikipedia/GoldbachConjecture.lean#goldbach --network-commit "$NETWORK" $( [ "$MODE" = "--sandbox" ] && echo --sandbox || echo --no-toolchain ) | tail -3
uv run --frozen --project "$ROOT" python -m opn_gate.cli intake import-fc "$HERE/upstream/FormalConjectures/Wikipedia/Schanuel.lean" --at "$PIN" --graph "$GRAPH" --target schanuel-conjecture --from "$HERE/schanuel-conjecture/record.yaml" --witness "$HERE/schanuel-conjecture/Witness.lean" --statement "$HERE/schanuel-conjecture/Statement.lean" --path FormalConjectures/Wikipedia/Schanuel.lean --repo google-deepmind/formal-conjectures --url "https://github.com/google-deepmind/formal-conjectures/blob/$PIN/FormalConjectures/Wikipedia/Schanuel.lean" --licence Apache-2.0 --attribution "The Formal Conjectures Authors (google-deepmind/formal-conjectures), Apache-2.0" --upstream-author "The Formal Conjectures Authors" --author "$AUTHOR" --evidence-from "$ROOT/docs/lean_conjecture_catalog.json" --key fc:FormalConjectures/Wikipedia/Schanuel.lean#schanuel_conjecture --network-commit "$NETWORK" $( [ "$MODE" = "--sandbox" ] && echo --sandbox || echo --no-toolchain ) | tail -3
